function permutations(values, path = []) {
  if (values.length === 0) {
    console.log(path);
    return;
  }

  for (let index = 0; index < values.length; index++) {
    const remaining = values.filter((_, itemIndex) => itemIndex !== index);
    permutations(remaining, [...path, values[index]]);
  }
}

permutations([1, 2, 3]);

const activities = [
  { name: 'A', start: 1, end: 3 },
  { name: 'B', start: 2, end: 5 },
  { name: 'C', start: 4, end: 7 }
];

activities.sort((left, right) => left.end - right.end);
const selected = [];
let lastEnd = -Infinity;

for (const activity of activities) {
  if (activity.start >= lastEnd) {
    selected.push(activity.name);
    lastEnd = activity.end;
  }
}

console.log(selected);

